"""Stage 28 step 10 -- OFFLINE. Renders report.md. Nothing is requested."""
from __future__ import annotations

import json
from pathlib import Path

STAGE = Path(__file__).resolve().parents[1]
RAW = STAGE / "raw"


def load(name):
    return json.loads((RAW / name).read_text(encoding="utf-8"))


all15 = load("all15_result.json")["cards"]
dish_decl, dish = load("dishwasher_declaration.json"), load("dishwasher_result.json")
study_decl, study = load("route_study_declaration.json"), load("route_study_result.json")
match, proposal = load("route_match.json"), load("batch5_proposal.json")
by = {c["article"]: c for c in all15}
VERDICT = {"export_ready": "готова к выгрузке", "export_ready_with_gaps": "готова с пробелами", "needs_verification": "нужна проверка варианта", "not_ready": "не готова"}
LEVEL = {"full_sku": "полный артикул (разметка/заголовок)", "code_in_page_text": "код только в тексте страницы", "base_model": "только базовая модель"}

lines = ["# Stage 28: русский PDF посудомоечной машины, размеры и вес робота-пылесоса, маршрут к следующим категориям", ""]
robot = by["VR50T95735W/EV"]
split = robot["device_split"]
facts = next(f["facts"] for f in dish["files"] if f.get("facts"))
lines += ["## Итог", "",
          f"- **Посудомоечная машина**: одна ограниченная попытка выполнена по объявленному заранее бюджету ({dish['budget']['spent']} фактический HTTP-запрос из {dish_decl['budget']['max_real_http_requests']} допустимых, потолок {dish_decl['budget']['document_ceiling_bytes'] // 1_000_000} МБ, известная ссылка, действующая защита доступа, остановок нет). Файл получен ({next(f['bytes'] for f in dish['files']) / 1e6:.1f} МБ, {facts['pages']} страниц), по тексту русский, в тексте назван точный код `DW60M5050BB`, противоречащей модели нет, страница с полным артикулом сама печатает ссылку: инструкция принята, карточка готова.",
          f"- **Робот-пылесос**: по сохранённой странице и инструкции размеры и вес отнесены к устройствам только по явной связи: {len(split['assigned'])} строк (робот и станция очистки); {len(split['unassigned'])} строки без явной связи оставлены с исходными значениями и статусом проверки. Вас назначать значения не прошу.",
          f"- **Маршрут**: установлен наблюдаемый маршрут (официальный индекс `b2c-sitemap.xml` → `memory-sitemap.xml`, `im-sitemap.xml`, `assorted-sitemap.xml`; {study['budget']['spent']} запроса из 4, только карты сайта). Из 15 оставшихся категорий 7 получили точные страницы, 8 — нет. Предложены две небольшие группы (4 + 3 категории), ничего не запускалось.",
          "- Каталог, реестр источников и `data/batches.sqlite3` не менялись (`protected_hashes_check.json`). Остальные категории остаются в очереди, массового прогона не было.", ""]

lines += ["## Посудомоечная машина DW60M5050BB/WT", "",
          f"- Объявление до запроса: `raw/dishwasher_declaration.json` ({dish_decl['declared_at']}; старт {dish['started_at']}). Кандидат: ссылка, напечатанная официальной страницей в этапе 27 (`{dish_decl['candidate']['file_name']}`); имя файла делает его лишь кандидатом, до чтения текста это ничего не доказывает.",
          f"- Результат: файл получен целиком (один запрос, 200), текст прочитан: русский по тексту, точный код каталога назван, связь со страницей — точная (`{facts['acceptance']['basis']}`). Файл сохранён как доказательство для обычного пути (`product_tool/config/samsung_recorded_documents.v1.json`): повторная загрузка не нужна, лимит по умолчанию остаётся 40 МБ.",
          "- Правило на случай неудачи закреплено в коде и тестах: если файл не получен целиком или не прочитан, статус — «кандидат на русскую инструкцию не проверен» (`instruction_russian_candidate_not_verified`), не «русской инструкции нет»; сохранённый английский файл русский не заменяет (отдельный справочный пробел `instruction_only_non_russian_file_saved`). Это поведение проверено на сохранённых ответах прежнего прогона (лимит 40 МБ).", ""]

lines += ["## Робот-пылесос VR50T95735W/EV: какие размеры и вес к какому устройству", "",
          "Доказательства (только явные): таблицы технических данных в русской инструкции — блок серии `VR50T95****` (изделие; стр. 48) и блок с названием «Станция очистки» (стр. 49) — плюс собственное название группы на странице «Детали Станции очистки (Аксессуары)». Строка страницы относится к устройству, только если её значение совпадает со значением таблицы, названной этим устройством, и совпадает ровно с одной таблицей. Порядок строк не используется (проверено переворотом списка в тесте).", "",
          "| Группа страницы | Строка | Значение | Устройство | Основание |", "|---|---|---|---|---|"]
for r in split["assigned"]:
    lines.append(f"| {r['group']} | {r['row']} | {r['value']} | {'робот-пылесос (основное изделие)' if r['device'] == 'product' else 'станция очистки'} | {r['basis']} |")
lines += ["", "Без явной связи (оба исходных значения сохранены как напечатаны, статус — проверка):", "", "| Группа страницы | Строка | Значение | Почему |", "|---|---|---|---|"]
for u in split["unassigned"]:
    lines.append(f"| {u['group']} | {u['row']} | {u['value']} | {u['reason']} |")
lines += ["",
          "- Сохранены исходные строки: «Вес 9.5 кг», «Размеры (ШxВxГ) 305x544x450 мм» и рядом «Вес Комплекта 4.4 кг», «Вес Нетто 9.5 кг». Единственный оставшийся конфликт значений — `product_weight`: «Вес 9.5» против «Вес Комплекта 4.4» (в реальном прогоне их было два поля-конфликта).",
          "- Арифметика 4,4 + 5,1 = 9,5 кг намекает, что 9,5 — вес робота со станцией, но это вывод, а не связь в данных; я её не применял.",
          f"- Итог по карточке: задание `{robot['job_status']}`, готовность «{VERDICT[robot['readiness']['verdict']]}»; открыта проверка `samsung_device_values_check`.", ""]

lines += ["## Маршрут к остальным категориям", "",
          f"Объявление до запросов: `raw/route_study_declaration.json` ({study_decl['declared_at']}). Наблюдаемый маршрут: официальный индекс `kz_ru/b2c-sitemap.xml`, перечисленные им карты сайта; страницы товаров, документы и картинки не запрашивались, адреса не строились. Запросов: {study['budget']['spent']} из {study['budget']['max']} (индекс и три карты, все 200), остановок нет. Индекс сегодня перечисляет: " + ", ".join(u.rsplit("/", 1)[-1] for u in study["index_listed_now"]) + ".", "",
          "| Категория (строк в каталоге) | Строк с точной страницей в картах | Карта | Предложенный товар | Раздел сайта |", "|---|---|---|---|---|"]
for category, e in match["categories"].items():
    p = e.get("proposed")
    lines.append(f"| {category} ({e['catalog_rows']}) | {e['rows_with_exact_page']} | {', '.join(e['by_sitemap']) or '—'} | {p['article'] if p else '—'} | {p['section'] if p else 'страниц в наблюдаемых картах нет'} |")
lines += ["", "Для смарт-часов и фитнес-браслетов страница в актуальной карте сайта — официальное подтверждение, что модель текущая (правило «только новинки»).", ""]

lines += ["## Предложение следующих групп (ничего не запускалось)", ""]
for name, g in proposal["groups"].items():
    b = g["request_budget"]
    lines += [f"### Группа {name}", "", "| Категория | Артикул | Карта |", "|---|---|---|"] + [f"| {c} | {p['article']} | {p['sitemap']} |" for c, p in g["products"].items()]
    lines += ["", f"Бюджет (объявляется до запросов): карты — {b['sitemaps']}; страницы {b['product_pages']}; файлы инструкций {b['instruction_files']}; итого не более {b['total_cap']}, не более 7 на строку; пауза 1,5 с; файл до 40 МБ; остановка при 401/403/429 или подтверждённом челлендже; дилер — 0 запросов.", f"Известный риск: {g['known_risk']}.", ""]
lines += ["Порядок: сначала 5A (одна карта, четыре категории), затем 5B. Категории без страниц в наблюдаемых картах: " + ", ".join(proposal["categories_still_without_a_route"]) + " — остаются в очереди; для них нужен другой наблюдаемый маршрут, адреса не угадываются.", ""]

lines += ["## Технический статус задания и готовность карточки (15 карточек) и причина каждого пробела", "",
          "| Категория | Артикул | Статус задания | Готовность | Вариант по странице | Фото выбрано/найдено |", "|---|---|---|---|---|---|"]
for c in all15:
    r = c["readiness"]
    lines.append(f"| {c['category']} | {c['article']} | `{c['job_status']}` | {VERDICT[r['verdict']]} | {LEVEL.get(r['page_match_level'])} | {r['official_photos_selected']}/{r['official_photos']} |")
lines += ["", "Статус задания (`done` — полный артикул по разметке/заголовку и нет конфликтов; `needs_review` — иначе) и готовность считаются отдельно. Причины всех пробелов (блокирующих и справочных):", "", "| Карточка | Пробел | Вид | Причина |", "|---|---|---|---|"]
for c in all15:
    r = c["readiness"]
    for gap, reason in r["gap_reasons"].items():
        kind = "блокирующий" if gap in r["blocking_gaps"] else "справочный"
        lines.append(f"| {c['category']} ({c['article']}) | `{gap}` | {kind} | {reason} |")
lines += ["", "## Что остаётся человеку", "",
          "- Galaxy A37, холодильник, варочная панель — вариант не подтверждён содержимым страницы (без изменений); у холодильника и A37 фото без привязки, у варочной панели скан вместо текста.",
          "- Робот-пылесос — проверка неотнесённых значений веса и размера; назначать наугад не требуется, карточка остаётся с исходными значениями.",
          "- Запуск групп 5A и 5B — по вашему слову, с объявленным бюджетом.", ""]
(STAGE / "report.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("report.md", len(lines), "lines")
